using UnityEngine.InputSystem;
[InitializeOnLoad]
internal static class MedicineFlowVerification
{
 const string Key="MedicineFlowTest.State";
 static Component flow,checkin,actor; static Camera camera; static Transform player; static int phase,frames; static float started,recoveryStart; static double deadline; static bool pressed; static List<string> logs=new List<string>();
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static MedicineFlowVerification(){var s=SessionState.GetString(Key,"Idle");if(s=="WaitingForCompile")EditorApplication.delayCall+=()=>{SessionState.SetString(Key,"EnteringPlayMode");EditorApplication.playModeStateChanged+=Changed;EditorApplication.isPlaying=true;};else if(s=="EnteringPlayMode"){EditorApplication.playModeStateChanged+=Changed;if(EditorApplication.isPlaying)Begin();}else if(s=="InPlayMode"&&EditorApplication.isPlaying)Begin();}
 static void Changed(PlayModeStateChange s){if(s==PlayModeStateChange.EnteredPlayMode)Begin();}
 static void Begin(){EditorApplication.playModeStateChanged-=Changed;SessionState.SetString(Key,"InPlayMode");deadline=EditorApplication.timeSinceStartup+65;EditorApplication.update+=Tick;}
 static object F(object o,string n){return o.GetType().GetField(n,flags).GetValue(o);} static void S(object o,string n,object v){o.GetType().GetField(n,flags).SetValue(o,v);} static object P(object o,string n){return o.GetType().GetProperty(n,flags).GetValue(o);} static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,flags).Invoke(o,a);}
 static void Log(string s){logs.Add(s);Debug.Log("[Test] "+s);} static void Require(bool b,string s){Log(s+"="+b);if(!b)throw new Exception(s);}
 static void KeyPress(bool down){var k=Keyboard.current;using(UnityEngine.InputSystem.LowLevel.StateEvent.From(k,out var e)){k.eKey.WriteValueIntoEvent(down?1f:0f,e);UnityEngine.InputSystem.InputSystem.QueueEvent(e);}}
 static string Stage(){return P(flow,"Stage").ToString();}
 static void Aim(Vector3 point,Vector3 outward,float distance){var pos=point+outward*distance;player.position=pos-Vector3.up*2;camera.transform.SetPositionAndRotation(pos,Quaternion.LookRotation(point-pos,Vector3.up));Physics.SyncTransforms();}
 static void Setup(){
 foreach(var root in UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true)){var c=t.GetComponent("AAH_RoomTreatmentSequence");if(c!=null)flow=c;}
 checkin=(Component)F(flow,"_checkIn");camera=(Camera)F(flow,"_playerCamera");player=(Transform)F(flow,"_player");
 foreach(var c in player.GetComponents<Behaviour>())if(c.GetType().Name=="SC_FPSController")c.enabled=false;var cc=player.GetComponent<CharacterController>();if(cc!=null)cc.enabled=false;
 var arrival=checkin.GetComponent("AAH_PatientArrivalController") as MonoBehaviour;arrival.StopAllCoroutines();
 var profiles=(Array)F(arrival,"_patients");var profile=profiles.GetValue(0);var registry=F(checkin,"roomRegistry");var room=Call(registry,"Reserve","PAT-001");var approach=(Transform)F(room,"bedApproach");
 UnityEngine.AI.NavMeshHit hit;Require(UnityEngine.AI.NavMesh.SamplePosition(approach.position,out hit,2,UnityEngine.AI.NavMesh.AllAreas),"Bed approach on NavMesh");
 var go=new GameObject("MedicineFlowTestPatient");go.SetActive(false);go.transform.position=hit.position;actor=go.AddComponent(Type.GetType("AAH_PatientActor, Assembly-CSharp"));var agent=go.GetComponent<UnityEngine.AI.NavMeshAgent>();agent.agentTypeID=-1372625422;agent.speed=8;agent.radius=0.5f;agent.height=3;go.SetActive(true);
 var doors=new List<Component>();foreach(var root in UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true)){var d=t.GetComponent("AAH_PatientDoorAccess");if(d!=null)doors.Add(d);}var doorArray=Array.CreateInstance(Type.GetType("AAH_PatientDoorAccess, Assembly-CSharp"),doors.Count);for(int i=0;i<doors.Count;i++)doorArray.SetValue(doors[i],i);
 Call(actor,"Initialize",profile,"PAT-001",registry,doorArray);S(actor,"<RoomNumber>k__BackingField",1);S(actor,"<State>k__BackingField",Enum.Parse(actor.GetType().GetProperty("State").PropertyType,"AtBed"));agent.enabled=false;Call(registry,"Occupy","PAT-001",1);
 var visual=(Transform)F(actor,"_visual");var b=(Bounds)P(actor,"VisualBounds");var bed=(Transform)F(room,"bedPose");visual.position+=bed.position-b.center;
 S(flow,"_patient",actor);Call(flow,"PreparePatient");Call(flow,"ShowMedicineImages",true);Call(flow,"BeginMedicineDelivery");Require(Stage()=="CollectingMedicine","Delivery starts");Require(Mathf.Abs((float)F(flow,"_treatmentDuration")-10)<0.01f,"Configured recovery is 10s");
 ((MonoBehaviour)checkin).StartCoroutine((IEnumerator)Call(checkin,"RegisteringRoutine"));started=Time.time;phase=1;
 }
 static void Tick(){if(++frames<5)return;try{if(phase==0){Setup();return;}if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Timeout phase="+phase+" stage="+Stage()+" actor="+P(actor,"State"));
 if(pressed){KeyPress(false);pressed=false;return;}
 if(phase==1){if(Time.time-started<3.4f)return;Require(((UnityEngine.UI.Image)F(checkin,"_receptionProgress")).fillAmount==1,"Reception progress reaches 100%");Capture(((UnityEngine.UI.Image)F(checkin,"_receptionProgress")).canvas,"Assets/MedicineTestReception.png");phase=2;}
 if(phase==2){int count=(int)P(flow,"CollectedMedicineCount");if(count>=2){Require(((RectTransform)F(flow,"_guideArrow")).gameObject.activeSelf,"Guidance arrow active");Call(flow,"UpdateDelivery");Require(((TMPro.TMP_Text)F(flow,"_guideText")).text.Contains("Về phòng"),"Guide switches to patient after collecting all medicines");phase=3;return;}var orders=(IList)F(flow,"_orders");var order=orders[count];var stock=F(order,"stock");var bottles=(GameObject[])F(stock,"bottles");var bottle=bottles[0];var proxy=bottle.GetComponentInChildren<BoxCollider>();Vector3 outward=bottle.transform.position.x<145?Vector3.right:Vector3.left;Aim(proxy.bounds.center,outward,1.6f);Require((bool)Call(flow,"SelectDeliveryTarget"),"Prescribed shelf bottle selectable "+count);KeyPress(true);pressed=true;return;}
 if(phase==3){Require((int)P(flow,"CollectedMedicineCount")==2,"Two prescribed medicines collected");var patientCollider=(Collider)F(flow,"_patientCollider");Aim(patientCollider.bounds.center,Vector3.up,2.5f);Call(flow,"Update");Require((bool)P(flow,"IsFocused"),"Patient selectable with held medicine");var outlines=(IList)F(flow,"_patientOutline");Require(outlines.Count>0&&((GameObject)outlines[0]).activeSelf,"Patient hover outline lights up");KeyPress(true);pressed=true;phase=4;return;}
 if(phase==4){if((int)P(flow,"DeliveredMedicineCount")==1){Require(Stage()=="CollectingMedicine","One medicine does not start recovery");KeyPress(true);pressed=true;return;}Require((int)P(flow,"DeliveredMedicineCount")==2&&Stage()=="Treating","All medicines deposited with E start treatment");recoveryStart=Time.time;phase=5;return;}
 if(phase==5){float progress=(float)P(flow,"TreatmentProgress");if(progress>0.35f&&progress<0.7f&&!SessionState.GetBool("MedicineFlowTest.Captured",false)){Capture(((UnityEngine.UI.Image)F(flow,"_treatmentFill")).canvas,"Assets/MedicineTestTV.png");SessionState.SetBool("MedicineFlowTest.Captured",true);Require(((GameObject)F(flow,"_treatmentPanel")).activeSelf,"TV progress panel visible");}if(Stage()!="Discharged")return;Log("Recovery elapsed="+(Time.time-recoveryStart));Require(Time.time-recoveryStart>=9.5f,"Recovery does not finish early");Require(!((GameObject)F(flow,"_treatmentPanel")).activeSelf,"TV progress hidden after recovery");Require(((TMPro.TMP_Text)F(flow,"_medicineText")).text=="","TV returns to black");Require(P(actor,"State").ToString()=="Leaving","Patient starts leaving");phase=6;return;}
 if(phase==6){if(actor.gameObject.activeSelf)return;Require(P(actor,"State").ToString()!="Blocked","Patient successfully exits");var registry=F(checkin,"roomRegistry");var rooms=(Array)P(registry,"Rooms");Require(F(rooms.GetValue(0),"owner")==null,"Room released after patient exits");Finish("PASS\n"+string.Join("\n",logs));}
 }catch(Exception e){Finish("FAIL "+e+"\n"+string.Join("\n",logs));}}
 static void Capture(Canvas canvas,string path){Canvas.ForceUpdateCanvases();foreach(var text in canvas.GetComponentsInChildren<TMPro.TMP_Text>())text.ForceMeshUpdate();var go=new GameObject("VerificationCamera");var cam=go.AddComponent<Camera>();cam.transform.SetPositionAndRotation(canvas.transform.position-canvas.transform.forward*10,Quaternion.LookRotation(canvas.transform.forward,canvas.transform.up));cam.orthographic=true;var rect=canvas.transform as RectTransform;cam.orthographicSize=rect.rect.height*canvas.transform.lossyScale.y*0.55f;cam.nearClipPlane=0.1f;cam.farClipPlane=12;var rt=new RenderTexture(1280,900,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,900),0,0);tex.Apply();System.IO.File.WriteAllBytes(path,tex.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(tex);UnityEngine.Object.Destroy(go);}
 static void Finish(string result){EditorApplication.update-=Tick;SessionState.SetString("MedicineFlowTest.Result",result);SessionState.SetString(Key,"Done");EditorApplication.isPlaying=false;}
}
